    #[test]
    fn ac031_invalid_type_name_produces_the_exact_error_prefix() {
        let r = AgentResponse::new("items[bad]");
        let out = r.render(OutputFormat::Text);
        assert!(out.starts_with("error: toon_validation_failed\nmessage: "), "got: {out}");
