        let r = AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a", "b"]);
        let out = r.render(OutputFormat::Text);
        assert_eq!(out, "error: toon_validation_failed\nmessage: row 0 has 1 values but 2 fields declared\n");
