        let from_string = CallToolResult::new(vec![], false, "raw".to_string());
        assert_eq!(from_str.structured_content, "raw");
        assert_eq!(from_string.structured_content, "raw");
        assert_eq!(from_str.content, vec![]);
        assert!(!from_str.is_error);
