name: Release & Publish

on:
  push:
    branches: [main]

permissions: {}

concurrency:
  group: release-${{ github.sha }}
  cancel-in-progress: false

jobs:
  plan:
    name: Identify a Callisto release commit
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: read
    outputs:
      isReleasePr: ${{ steps.candidate.outputs.isReleasePr }}
      releaseSourceSha: ${{ steps.candidate.outputs.releaseSourceSha }}
      nativeMatrix: ${{ steps.matrix.outputs.nativeMatrix }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false

      - uses: orin-dx/callisto/.github/actions/setup-callisto@0a971b2118954e7089c1a0aa28aebbf131ed1602 # callisto@0.10.0
        with:
          version: callisto@0.10.0
          verification: fallback

      - name: Verify merged release PR
        id: candidate
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
          RELEASE_SOURCE_SHA: ${{ github.sha }}
        run: |
          set -euo pipefail
          prs=$(gh api --paginate --slurp "/repos/${GITHUB_REPOSITORY}/commits/${RELEASE_SOURCE_SHA}/pulls" \
            --jq '[.[][] | select(.merged_at != null and .base.ref == "main" and
              .head.repo.full_name == "'"${GITHUB_REPOSITORY}"'" and
              (.head.ref == "callisto/version-packages" or
               (.head.ref | test("^callisto/version-packages--[0-9a-f]{40}$"))))] | length')
          verified=$(gh api "/repos/${GITHUB_REPOSITORY}/commits/${RELEASE_SOURCE_SHA}" \
            --jq '.commit.verification.verified')
          if [[ "$prs" == 1 && "$verified" == true ]]; then
            {
              echo 'isReleasePr=true'
              echo "releaseSourceSha=$RELEASE_SOURCE_SHA"
            } >> "$GITHUB_OUTPUT"
          else
            {
              echo 'isReleasePr=false'
              echo "releaseSourceSha=$RELEASE_SOURCE_SHA"
            } >> "$GITHUB_OUTPUT"
          fi

      - name: Compute NAPI build matrix
        id: matrix
        shell: bash
        run: |
          set -euo pipefail
          matrix=$(callisto matrix --format json | jq -c \
            '[.platformTargets[] | select(.kind == "napi") | .targets[]] | unique_by(.artifactName)')
          expected='["michi-node-darwin-arm64","michi-node-linux-x64-gnu","michi-node-linux-x64-musl"]'
          actual=$(jq -c '[.[].artifactName] | sort' <<< "$matrix")
          if [[ "$actual" != "$expected" ]]; then
            echo "::error::Unexpected NAPI targets: $actual"
            exit 1
          fi
          echo "nativeMatrix=$matrix" >> "$GITHUB_OUTPUT"

  version-pr:
    name: Create or update the Callisto version PR
    needs: plan
    if: needs.plan.outputs.isReleasePr != 'true'
    runs-on: ubuntu-latest
    concurrency:
      group: callisto-version-pr
      cancel-in-progress: false
    permissions:
      contents: write
      pull-requests: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false

      - name: Create or update version PR
        uses: orin-dx/callisto/.github/actions/callisto-action@0a971b2118954e7089c1a0aa28aebbf131ed1602 # callisto@0.10.0
        with:
          mode: version-pr
          version: callisto@0.10.0
          branch: main
          release_branch: callisto/version-packages
          version_command: callisto version --refresh-lockfiles
        env:
          GH_TOKEN: ${{ github.token }}

  build-native:
    name: Build native (${{ matrix.triple }})
    needs: plan
    if: >-
      needs.plan.outputs.isReleasePr == 'true'
    strategy:
      fail-fast: false
      matrix:
        include: ${{ fromJson(needs.plan.outputs.nativeMatrix) }}
    runs-on: ${{ matrix.hostRunner }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.plan.outputs.releaseSourceSha }}
          persist-credentials: false

      - uses: orin-dx/actions/setup-rust@v1.1
        with:
          targets: ${{ matrix.triple }}
          cache-key: ${{ matrix.triple }}

      - uses: orin-dx/actions/setup-proto-node-pnpm@v1.1
        with:
          working-directory: packages/michi-node

      - run: pnpm install --frozen-lockfile
        working-directory: packages/michi-node

      - name: Install ziglang for cross compilation
        if: matrix.useCross
        run: pip install ziglang

      - name: Cache cargo-zigbuild
        if: matrix.useCross
        id: zigbuild-cache
        uses: actions/cache@v4
        with:
          path: ~/.cargo/bin/cargo-zigbuild
          key: ${{ runner.os }}-cargo-zigbuild-${{ matrix.triple }}

      - name: Install cargo-zigbuild
        if: matrix.useCross && steps.zigbuild-cache.outputs.cache-hit != 'true'
        run: cargo install cargo-zigbuild --locked

      - name: Build NAPI target
        working-directory: packages/michi-node
        run: pnpm build --target ${{ matrix.triple }} ${{ matrix.useCross && '--cross-compile' || '' }}

      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: ${{ matrix.artifactName }}
          path: packages/michi-node/*.node
          if-no-files-found: error
          retention-days: 7

  release:
    name: Publish verified release
    needs: [plan, build-native]
    if: >-
      always() && needs.plan.result == 'success' &&
      needs.plan.outputs.isReleasePr == 'true' && needs.build-native.result == 'success'
    runs-on: ubuntu-latest
    permissions:
      contents: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ needs.plan.outputs.releaseSourceSha }}
          fetch-depth: 0

      - uses: orin-dx/actions/setup-proto-node-pnpm@v1.1
        with:
          working-directory: packages/michi-node
          cache: 'false'

      - run: pnpm install --frozen-lockfile
        working-directory: packages/michi-node

      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          pattern: michi-node-*
          path: ${{ runner.temp }}/michi-native
          merge-multiple: true

      - name: Check and collect all native targets
        working-directory: packages/michi-node
        env:
          NATIVE_DIR: ${{ runner.temp }}/michi-native
        run: |
          set -euo pipefail
          for file in \
            michi.darwin-arm64.node \
            michi.linux-x64-gnu.node \
            michi.linux-x64-musl.node; do
            if [[ ! -f "$NATIVE_DIR/$file" ]]; then
              echo "::error::Missing native artifact: $file"
              exit 1
            fi
          done
          pnpm exec napi create-npm-dirs
          pnpm exec napi artifacts --output-dir "$NATIVE_DIR"
          for file in \
            michi.darwin-arm64.node \
            michi.linux-x64-gnu.node \
            michi.linux-x64-musl.node; do
            if [[ ! -f "$file" ]]; then
              echo "::error::NAPI artifact collection did not place $file in the root package"
              exit 1
            fi
          done

      - name: Configure npm authentication
        shell: bash
        env:
          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}
          NPM_CONFIG_USERCONFIG: ${{ runner.temp }}/michi-npmrc
        run: |
          set -euo pipefail
          printf '//registry.npmjs.org/:_authToken=%s\n' "$NPM_TOKEN" > "$NPM_CONFIG_USERCONFIG"

      - name: Publish with Callisto 0.10.0
        uses: orin-dx/callisto/.github/actions/callisto-action@0a971b2118954e7089c1a0aa28aebbf131ed1602 # callisto@0.10.0
        with:
          mode: release
          version: callisto@0.10.0
        env:
          CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}
          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}
          NPM_CONFIG_USERCONFIG: ${{ runner.temp }}/michi-npmrc
          GH_TOKEN: ${{ github.token }}
name: CI

on:
