/// NAPI wrapper around [`crate::response::AgentResponse`].
#[napi(js_name = "AgentResponse")]
#[derive(Debug)]
pub struct JsAgentResponse {
    inner: Option<michi_core::response::AgentResponse>,
    /// Cumulative count of [`Self::hint`] calls, capped at [`MAX_HINTS`].
    hint_count: usize,
    /// Cumulative count of [`Self::recovery_hint`] calls, capped at [`MAX_HINTS`].
    recovery_count: usize,
}

#[napi]
impl JsAgentResponse {
    /// Create a new response builder for the given type name.
    #[napi(constructor, catch_unwind)]
    #[must_use]
    pub fn new(type_name: String) -> Self {
        Self { inner: Some(michi_core::response::AgentResponse::new(type_name)), hint_count: 0, recovery_count: 0 }
    }

    fn take(&mut self) -> napi::Result<michi_core::response::AgentResponse> {
        self.inner.take().ok_or_else(|| napi::Error::from_reason("AgentResponse already consumed"))
    }

    /// Populate the TOON list path.
    #[napi(catch_unwind)]
    #[allow(clippy::needless_pass_by_value)] // napi-derive requires owned Vec<String> for JS array params
    pub fn items(&mut self, rows: Vec<Vec<JsToonValue>>, fields: Vec<String>) -> napi::Result<()> {
        if rows.len() > MAX_ROWS {
            return Err(napi::Error::from_reason(format!("rows length {} exceeds maximum of {MAX_ROWS}", rows.len())));
        }
        if fields.len() > MAX_FIELDS {
            return Err(napi::Error::from_reason(format!(
                "fields length {} exceeds maximum of {MAX_FIELDS}",
                fields.len()
            )));
        }
        for row in &rows {
            if row.len() > MAX_FIELDS {
                return Err(napi::Error::from_reason(format!(
                    "row length {} exceeds maximum of {MAX_FIELDS}",
                    row.len()
                )));
            }
        }
        let field_refs: Vec<&str> = fields.iter().map(String::as_str).collect();
        let converted: Vec<Vec<michi_toon::Value>> = rows
            .into_iter()
            .map(|row| row.into_iter().map(js_value_to_rust).collect::<napi::Result<Vec<_>>>())
            .collect::<napi::Result<Vec<_>>>()?;
        let b = self.take()?;
        self.inner = Some(b.items(converted, &field_refs));
        Ok(())
    }

    /// Set the total available count (TOON path only).
    #[napi(catch_unwind)]
    pub fn total_count(&mut self, #[napi(ts_arg_type = "number")] n: JsCount) -> napi::Result<()> {
        let b = self.take()?;
        self.inner = Some(b.total_count(n.get()));
        Ok(())
    }

    /// Populate the KV single-item path.
    #[napi(catch_unwind)]
    pub fn kv_items(&mut self, items: Vec<JsKvItem>) -> napi::Result<()> {
        if items.len() > MAX_FIELDS {
            return Err(napi::Error::from_reason(format!(
                "items length {} exceeds maximum of {MAX_FIELDS}",
                items.len()
            )));
        }
        let converted = items
            .into_iter()
            .map(|i| Ok(michi_core::kv::KvItem { key: i.key, value: js_kv_value_to_rust(i.value)? }))
            .collect::<napi::Result<Vec<_>>>()?;
        let b = self.take()?;
        self.inner = Some(b.kv_items(converted));
        Ok(())
    }

    /// Append a contextual hint.
    #[napi(catch_unwind)]
    pub fn hint(&mut self, hint: String) -> napi::Result<()> {
        if self.hint_count >= MAX_HINTS {
            return Err(napi::Error::from_reason(format!("cumulative hint count exceeds maximum of {MAX_HINTS}")));
        }
        let b = self.take()?;
        self.inner = Some(b.hint(hint));
        self.hint_count += 1;
        Ok(())
    }

    /// Append a recovery hint naming a tool.
    #[napi(catch_unwind)]
    pub fn recovery_hint(&mut self, tool: String, reason: Option<String>) -> napi::Result<()> {
        if self.recovery_count >= MAX_HINTS {
            return Err(napi::Error::from_reason(format!(
                "cumulative recovery hint count exceeds maximum of {MAX_HINTS}"
            )));
        }
        let b = self.take()?;
        let mut hint = michi_core::recovery::RecoveryHint::new(tool);
        if let Some(reason) = reason {
            hint = hint.reason(reason);
        }
        self.inner = Some(b.recovery_hint(hint));
        self.recovery_count += 1;
        Ok(())
    }

    /// Mark this response as an error state.
    #[napi(catch_unwind)]
    pub fn as_error(&mut self) -> napi::Result<()> {
        let b = self.take()?;
        self.inner = Some(b.as_error());
        Ok(())
    }

    /// Attach a human-facing companion block (`audience: user`) for MCP callers.
    #[napi(catch_unwind)]
    pub fn human_content(&mut self, text: String) -> napi::Result<()> {
        let b = self.take()?;
        self.inner = Some(b.human_content(text));
        Ok(())
    }

    /// Render via the TOON path (`items`/`fields`/`totalCount`), reading only
    /// that slot regardless of which of `.items()`/`.kvItems()` was called
    /// last — see [`crate::response::AgentResponse::render_toon`].
    ///
    /// # Errors
    ///
    /// Returns an error only if an internal invariant is violated (should not happen in normal use).
    #[napi(catch_unwind)]
    pub fn render_toon(&self) -> napi::Result<String> {
        self.inner
            .as_ref()
            .ok_or_else(|| napi::Error::from_reason("AgentResponse already consumed"))
            .map(crate::response::AgentResponse::render_toon)

/// A single operation that failed within a larger multi-step operation.
#[derive(Debug, Clone, PartialEq)]
pub struct FailedOp {
    /// Identifier of the operation that failed.
    pub operation: String,
    /// Human-readable failure reason.
    pub reason: String,
    /// Optional structured recovery hint for this specific failure.
    pub recovery: Option<crate::recovery::RecoveryHint>,
}

/// Signals that an operation partially completed before a failure.
///
/// Use this when some steps of a multi-step operation succeeded — the agent
/// can resume from the checkpoint rather than retrying from scratch.
///
/// For a fully-completed prior call, see [`michi_resilience::AlreadyDone`]
/// and [`michi_resilience::already_done`].
#[derive(Debug, Clone, PartialEq)]
pub struct PartialSuccess {
    /// Identifiers of steps that completed successfully.
    pub completed: Vec<String>,
    /// Steps that failed, with reason and optional recovery hint.
    pub failed: Vec<FailedOp>,
    /// Identifiers of steps that were not attempted.
    pub skipped: Vec<String>,
}

impl PartialSuccess {
    /// Render as an agent-readable string: a summary line, one block per
    /// non-empty outcome category, then any per-op recovery hints folded into
    /// a trailing `help[]` block.
    ///
    /// Format:
    /// ```text
    /// partial_success: 2 completed, 1 failed, 1 skipped
    /// completed[2]:
    ///   create_issue
    ///   add_label
    /// failed[1]{operation,reason}:
    ///   assign_user,"User 'ghost' not found"
    /// skipped[1]:
    ///   notify_team
    /// help[1]:
    ///   assign_user: suggestedParams: { user: alice }
    /// ```
    ///
    /// Empty categories are omitted.
    #[must_use]
    pub fn render(&self) -> String {
        let mut out = String::with_capacity(
            64 + self.completed.iter().map(String::len).sum::<usize>()
                + self.failed.iter().map(|f| f.operation.len() + f.reason.len() + 60).sum::<usize>()
                + self.skipped.iter().map(String::len).sum::<usize>(),
        );
        out.push_str("partial_success: ");
        out.push_str(&self.completed.len().to_string());
        out.push_str(" completed, ");
        out.push_str(&self.failed.len().to_string());
        out.push_str(" failed, ");
        out.push_str(&self.skipped.len().to_string());
        out.push_str(" skipped\n");

        if !self.completed.is_empty() {
            out.push_str("completed[");
            out.push_str(&self.completed.len().to_string());
            out.push_str("]:\n");
            for op in &self.completed {
                out.push_str("  ");
                out.push_str(op);
                out.push('\n');
            }
        }

        if !self.failed.is_empty() {
            out.push_str("failed[");
            out.push_str(&self.failed.len().to_string());
            out.push_str("]{operation,reason}:\n");
            for f in &self.failed {
                out.push_str("  ");
                // operation: conditionally quoted (only when it contains commas/quotes/newlines)
                out.push_str(michi_toon::escape_value(&f.operation).as_ref());
                out.push(',');
                // reason: always quoted — it is human-readable prose and often contains quotes
                out.push_str(&michi_toon::escape_value_quoted(&f.reason));
                out.push('\n');
            }
        }

        if !self.skipped.is_empty() {
            out.push_str("skipped[");
            out.push_str(&self.skipped.len().to_string());
            out.push_str("]:\n");
            for op in &self.skipped {
                out.push_str("  ");
                out.push_str(op);
                out.push('\n');
            }
        }

        let recovery_hints: Vec<crate::recovery::RecoveryHint> =
            self.failed.iter().filter_map(|f| f.recovery.clone()).collect();
        if !recovery_hints.is_empty() {
            out.push_str("help[");
            out.push_str(&recovery_hints.len().to_string());
            out.push_str("]:\n");
            // Use inner append_recovery_lines (pub(crate)) to avoid the `recovery[N]:` header
            // that append_recovery would write — the section header here is `help[N]:`.
            crate::recovery::append_recovery_lines(&mut out, &recovery_hints);
        }

        out
    }

    /// `0` when all operations completed or were skipped; `1` when any failed.
    #[must_use]
    pub fn exit_code(&self) -> i32 {
        i32::from(!self.failed.is_empty())
    }
}

