    // just the completed+skipped-both-nonempty combination above.
    #[test]
    fn ac036_exit_code_zero_holds_when_completed_and_skipped_are_also_empty() {
        let ps = PartialSuccess { completed: vec![], failed: vec![], skipped: vec![] };
        assert_eq!(ps.exit_code(), 0);
    }

    #[test]
    fn partial_success_exit_code_one_when_any_failed() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: vec![FailedOp { operation: "x".into(), reason: "y".into(), recovery: None }],
            skipped: vec![],
        };
        assert_eq!(ps.exit_code(), 1);
    }

    // AC-037: exit_code()==1 regardless of how many entries failed contains
    // — the existing test above only proves the 1-entry case.
    #[test]
    fn ac037_exit_code_one_holds_for_five_failed_entries() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: (0..5)
                .map(|i| FailedOp { operation: format!("op{i}"), reason: "y".into(), recovery: None })
                .collect(),
            skipped: vec![],
        };
        assert_eq!(ps.exit_code(), 1);
    }

    #[test]
    fn failed_op_without_recovery_produces_no_help_block() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: vec![FailedOp { operation: "x".into(), reason: "y".into(), recovery: None }],
            skipped: vec![],
        };
        assert!(!ps.render().contains("help["));
    }

    #[test]
    fn operation_with_comma_is_escaped() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: vec![FailedOp {
                operation: "create_issue, retry 2".into(),
                reason: "timeout".into(),
                recovery: None,
            }],
            skipped: vec![],
        };
        let out = ps.render();
        // operation contains comma — must be quoted to avoid breaking TOON column parsing
        assert!(out.contains(r#""create_issue, retry 2""#), "operation must be quoted, got: {out}");
    }

    // AC-034: a newline/CR in operation, with no comma or quote present, is
    // silently stripped (not escaped) and does NOT by itself trigger quoting.
    #[test]
    fn ac034_newline_and_cr_in_operation_are_stripped_without_triggering_quoting() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: vec![FailedOp { operation: "step\none\rtwo".into(), reason: "y".into(), recovery: None }],
            skipped: vec![],
        };
        let out = ps.render();
        assert!(out.contains("  steponetwo,\"y\"\n"), "got: {out}");
    }

    // AC-035: recovery from a failed op appends a trailing help[] block with
    // no duplicate leading "recovery[N]:" header line.
    #[test]
    fn ac035_recovery_help_block_has_no_duplicate_recovery_header() {
        let ps = PartialSuccess {
            completed: vec![],
            failed: vec![FailedOp {
                operation: "x".into(),
                reason: "y".into(),
                recovery: Some(RecoveryHint::new("retry_x")),
            }],
            skipped: vec![],
        };
        let out = ps.render();
        assert!(out.contains("help[1]:\n  retry_x\n"), "got: {out}");
        assert!(!out.contains("recovery["), "must not duplicate a recovery[N]: header, got: {out}");
    }
}
use std::fmt::Write as _;

/// Status of an individual pipeline step.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
#[non_exhaustive]
pub enum StepStatus {
    /// Step completed successfully.
    Completed,
    /// Step was skipped.
    Skipped,
    /// Step failed.
    Failed,
    /// Step has not been attempted yet.
    Pending,
}

impl StepStatus {
    /// The short label string used in rendered output.
    #[must_use]
    pub fn label(&self) -> &'static str {
        match self {
            Self::Completed => "completed",
            Self::Skipped => "skipped",
            Self::Failed => "failed",
            Self::Pending => "pending",
        }
    }
}

/// A pipeline step definition.
#[derive(Debug, Clone)]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct PipelineStep {
    /// Step identifier.
    ///
    /// michi does not validate uniqueness — callers are responsible for ensuring
    /// step IDs are distinct within a pipeline if they intend to reference steps
    /// by ID. Duplicate IDs render without error but produce ambiguous output.
    pub id: String,
    /// Human-readable name.
    pub name: String,
    /// Current status.
    pub status: StepStatus,
}

/// A pipeline run state.
#[derive(Debug, Clone, Default)]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct Pipeline {
    /// Pipeline identifier.
    pub id: String,
    /// All steps in declaration order.
    pub steps: Vec<PipelineStep>,
}

impl Pipeline {
    /// Render the pipeline state as a TOON-style list.
    #[must_use]
    pub fn render(&self) -> String {
        let n = self.steps.len();
        let capacity = 30 + n * 40;
        let mut out = String::with_capacity(capacity);

        out.push_str("step[");
        let _ = write!(out, "{n}");
        out.push_str("]{id,name,status}:\n");

        for step in &self.steps {
            out.push_str("  ");
            out.push_str(&michi_toon::escape_value(&step.id));
            out.push(',');
            out.push_str(&michi_toon::escape_value(&step.name));
            out.push(',');
            out.push_str(step.status.label());
            out.push('\n');
        }

        out
    }
}

#[cfg(test)]
mod tests {
