    #[must_use]
    pub fn is_root_cause(&self) -> bool {
        matches!(
            self.status,
            StepStatus::Failed
                | StepStatus::OutcomeUnknown(_)
                | StepStatus::NotRun(_)
                | StepStatus::Panicked
                | StepStatus::Running
