    /// its effect may have happened: `OutcomeUnknown`, `Panicked` or `Running`.
    #[must_use]
    pub fn awaits_verification(&self) -> bool {
        matches!(self.status, StepStatus::OutcomeUnknown(_) | StepStatus::Panicked | StepStatus::Running)
    }
